// These short labels are used as arithmetic controls in the dashboard formula builder.
zh.Add = '加';
zh.Scale = '结果倍数';

const patterns: Array<[RegExp, (match: RegExpMatchArray) => string]> = [
  [/^Provider returned HTTP (\d+) while validating\.$/, (m) => `服务商验证接口返回 HTTP ${m[1]}，请检查 API 地址、密钥和模型服务状态。`],
  [/^Provider base URL DNS validation returned HTTP (\d+)\.$/, (m) => `API 基础地址的 DNS 验证返回 HTTP ${m[1]}，请稍后重试。`],
  [/^Provider base URL hostname resolves to a private, link-local, or reserved address\.$/, () => 'API 基础地址解析到了私有、链路本地或保留地址。'],
  [/^(\d+) configured$/, (m) => `${m[1]} 个配置`], [/^(\d+) recent cycles$/, (m) => `${m[1]} 个近期周期`], [/^(\d+) active$/, (m) => `${m[1]} 个进行中`], [/^(\d+) recorded$/, (m) => `${m[1]} 条记录`],
  [/^(\d+) products available$/, (m) => `${m[1]} 个可用产品`], [/^(\d+) providers$/, (m) => `${m[1]} 个服务商`], [/^(\d+) recent events$/, (m) => `${m[1]} 条最近事件`], [/^(\d+) members$/, (m) => `${m[1]} 位成员`],
  [/^(\d+) clients$/, (m) => `${m[1]} 个客户`], [/^(\d+) products$/, (m) => `${m[1]} 个产品`], [/^(\d+) specialists$/, (m) => `${m[1]} 位专家`], [/^(\d+) report schedules$/, (m) => `${m[1]} 个报告计划`],
  [/^(\d+) connected Bing accounts?$/, (m) => `${m[1]} 个已连接的 Bing 账户`], [/^Run (\d+) specialists$/, (m) => `运行 ${m[1]} 位专家`],
  [/^(\d+) queued · (\d+) running$/, (m) => `${m[1]} 个排队中 · ${m[2]} 个运行中`], [/^(\d+) errors · (\d+) cancelled$/, (m) => `${m[1]} 个错误 · ${m[2]} 个已取消`],
  [/^(\d+)\/([\d]+) remaining · resets (.+)$/, (m) => `${m[1]}/${m[2]} 剩余 · ${m[3]} 重置`],
  [/^(.+) · needs data$/, (m) => `${zh[m[1]] || m[1]} · 需要数据`], [/^(.+) · needs model\/data in this scope$/, (m) => `${zh[m[1]] || m[1]} · 当前范围需要模型或数据`],
  [/^(\d+) real products · latest not synced$/, (m) => `${m[1]} 个真实产品 · 最近尚未同步`],
  [/^(\d+) calculated metrics$/, (m) => `${m[1]} 个计算指标`], [/^Metric created; (\d+) calculated points refreshed\.$/, (m) => `指标已创建，已刷新 ${m[1]} 个计算结果。`],
  [/^(\d+) calculated points refreshed\.$/, (m) => `已刷新 ${m[1]} 个计算结果。`],
  [/^(.+) (increased|decreased|changed) for (.+)$/, (m) => `${m[3]} 的${zh[m[1]] || m[1]}${m[2] === 'increased' ? '增加了' : m[2] === 'decreased' ? '减少了' : '发生了变化'}`],
  [/^(.+) moved from (.+) to (.+) \(([+-]?[\d.]+%)\) between the two complete comparison windows\.$/, (m) => `在两个完整对比周期之间，${zh[m[1]] || m[1]}从 ${m[2]} 变为 ${m[3]}（${m[4]}）。`],
  [/^(.+) and (.+) are (moving together|diverging) for (.+)$/, (m) => `${m[4]} 的${zh[m[1]] || m[1]}与${zh[m[2]] || m[2]}${m[3] === 'moving together' ? '同向变化' : '走势分化'}`],
  [/^(.+) (increased|decreased|changed) (.+), while (.+) (increased|decreased|changed) (.+)\.$/, (m) => `${zh[m[1]] || m[1]}${m[2] === 'increased' ? '增加' : m[2] === 'decreased' ? '减少' : '变化'} ${m[3]}，而${zh[m[4]] || m[4]}${m[5] === 'increased' ? '增加' : m[5] === 'decreased' ? '减少' : '变化'} ${m[6]}。`],
  [/^(.+) health is (at risk|on watch)$/, (m) => `${m[1]} 的健康度${m[2] === 'at risk' ? '存在风险' : '需要关注'}`],
  [/^(\d+)\/100 deterministic health score\. (.+)$/, (m) => `确定性健康评分为 ${m[1]}/100。${m[2]}`],
  [/^(.+) goal has no matching evidence$/, (m) => `${m[1]} 的目标没有匹配数据`],
  [/^(.+) is (off track|at risk) on (.+)$/, (m) => `${m[1]} 的“${m[3]}”目标${m[2] === 'off track' ? '已偏离轨道' : '存在风险'}`],
  [/^(.+) has no matching data for the (.+) goal window\.$/, (m) => `${zh[m[1]] || m[1]}在${m[2]}目标周期内没有匹配数据。`],
  [/^(.+) is (.+) against a (.+) target \(([\d.]+)%\)\.$/, (m) => `${zh[m[1]] || m[1]}当前为 ${m[2]}，目标为 ${m[3]}（完成 ${m[4]}%）。`],
  [/^Sync (.+)$/, (m) => zh[m[1]] ? `同步${zh[m[1]]}` : m[0]], [/^Open (.+)$/, (m) => zh[m[1]] ? `打开${zh[m[1]]}` : m[0]], [/^Connect (.+)$/, (m) => zh[m[1]] ? `连接${zh[m[1]]}` : m[0]], [/^Create (.+)$/, (m) => zh[m[1]] ? `创建${zh[m[1]]}` : m[0]],
];

const protectedBrands = new Set(['Dashloom', 'Anyway', 'Waffo', 'Waffo Pancake', 'Cloudflare', 'Google', 'GitHub', 'Vercel', 'Supabase', 'Stripe', 'Polar', 'Paddle', 'Creem', 'Bing', 'Slack', 'Discord', 'Telegram', 'AWS']);

export function translateDashboard(value: string) {
  if (protectedBrands.has(value)) return value;
  if (Object.hasOwn(zh, value)) return zh[value];
  for (const [pattern, render] of patterns) { const match = value.match(pattern); if (match) return render(match); }
  return value;
}
